/**
 * Centralized default values for action inputs.
 * These are the source of truth - action.yml should match these values.
 */

export const DEFAULTS = {
	triggerPhrase: "@pi",
	allowedAssociations: ["OWNER", "MEMBER"],
	timeout: 1800,
	pollInterval: 15,
	provider: "anthropic",
	model: "claude-sonnet-5-5",
	customProviderApi: "openai-completions",
	customProviderAuthHeader: false,
	customModelReasoning: false,
	customModelInput: "text",
	customModelContextWindow: 128_000,
	customModelMaxTokens: 16_384,
	outputMode: "comment",
	trustProject: false,
	worktreeSnapshots: true,
} as const;
	return {
		triggerText: "@pi test",
		author: { login: "user", type: "User" },
		authorAssociation: "OWNER",
		issueNumber: 1,
		issueTitle: "Test",
		issueBody: "Body",
		isPullRequest: false,
		source: "body",
		...overrides,
	};
}

export function createActionInputs(
	overrides: Partial<ActionInputs> = {},
): ActionInputs {
	return {
		triggerPhrase: DEFAULTS.triggerPhrase,
		allowedBots: [],
		allowedUsers: [],
		allowedAssociations: [...DEFAULTS.allowedAssociations],
		provider: DEFAULTS.provider,
		model: DEFAULTS.model,
		timeout: DEFAULTS.timeout,
		githubToken: "test-token",
		apiKey: undefined,
		customProvider: undefined,
		promptTemplate: undefined,
		outputMode: DEFAULTS.outputMode,
		prompt: undefined,
		prNumber: undefined,
		pollInterval: DEFAULTS.pollInterval,
		extensions: [],
		trustProject: DEFAULTS.trustProject,
		agentDir: undefined,
		worktreeSnapshots: DEFAULTS.worktreeSnapshots,
		worktreeLimits: DEFAULT_SNAPSHOT_LIMITS,
		excludeTools: [],
		modelToolsHidden: [],
		...overrides,
	};
}

/** A faux provider in a fresh model registry, and the pi-durable agent config that uses its model. */
export function fauxModels(): {
	faux: ReturnType<typeof fauxProvider>;
	models: ReturnType<typeof createModels>;
	model: Model<Api>;
	agent: { model: { provider: string; modelId: string } };
} {
	const faux = fauxProvider();
	const models = createModels();
	models.setProvider(faux.provider);
	const model = faux.getModel();
	return {
		faux,
		models,
		model,
		agent: { model: { provider: model.provider, modelId: model.id } },
	};
}

/** Run git in `cwd` and return its output. */
export function git(cwd: string, ...args: string[]): string {
	return execFileSync("git", args, { cwd, encoding: "utf8" });
}

/** A temp directory, removed when the current test finishes. */
export function tempDir(prefix = "pi-action-"): string {
	const dir = mkdtempSync(join(tmpdir(), prefix));
	onTestFinished(() => {
import { readFileSync } from "node:fs";

import { describe, expect, it } from "vitest";

const ACTION_YML = readFileSync("action.yml", "utf8");
const README = readFileSync("README.md", "utf8");
const ACTION_INPUT_NAME_PATTERN = /^ {2}(\w+):$/gmu;
const DOC_INPUT_NAME_PATTERN = /^\| `([^`]+)` \|/gmu;

function compareStrings(left: string, right: string): number {
	return left.localeCompare(right);
}

function getActionInputNames(): string[] {
	const inputsBlock = ACTION_YML.slice(
		ACTION_YML.indexOf("inputs:"),
		ACTION_YML.includes("outputs:")
			? ACTION_YML.indexOf("outputs:")
			: ACTION_YML.indexOf("runs:"),
	);
	return [...inputsBlock.matchAll(ACTION_INPUT_NAME_PATTERN)].flatMap((match) =>
		match[1] ? [match[1]] : [],
	);
}

function getDocumentedInputNames(): string[] {
	const inputTableStart = README.indexOf(
		"| Input | Description | Required | Default |",
	);
	if (inputTableStart === -1) {
		throw new Error("README input table not found");
	}
	const nextHeading = README.slice(inputTableStart).indexOf("\n#");
	const inputTable = README.slice(
		inputTableStart,
		nextHeading === -1 ? undefined : inputTableStart + nextHeading,
	);
	return [...inputTable.matchAll(DOC_INPUT_NAME_PATTERN)].flatMap((match) =>
		match[1] ? [match[1]] : [],
	);
}

describe("action input documentation", () => {
	it("documents every action.yml input in the README inputs table", () => {
		expect(getDocumentedInputNames().toSorted(compareStrings)).toStrictEqual(
			getActionInputNames().toSorted(compareStrings),
		);
	});
});
